def transform(grid):
    # Background is the first element (most common color)
    bg = grid[0][0]

    result = []
    for row in grid:
        new_row = []
        for c, val in enumerate(row):
            if val == bg:
                new_row.append(bg)
            elif val == 0:
                # Check if 0 is part of a horizontal line of 3+
                count = 1
                # Check right
                for cc in range(c+1, len(row)):
                    if row[cc] == 0:
                        count += 1
                    else:
                        break
                # Check left
                for cc in range(c-1, -1, -1):
                    if row[cc] == 0:
                        count += 1
                    else:
                        break

                # Only keep 0 if in a line of 3+
                if count >= 3:
                    new_row.append(0)
                else:
                    new_row.append(bg)
            else:
                new_row.append(val)
        result.append(new_row)

    return result
